# Test class: Performance Under Repeated Imports
# ---------------------------------------------------------------------------

class TestRepeatedImportStability:
    """Ensures the package handles repeated imports gracefully."""

    def test_repeated_imports_no_leak(self):
        """
        Importing the package 100 times should not cause memory leaks
        or module count growth.
        """
        import gc

        # Warm up
        for _ in range(10):
            importlib.import_module(PACKAGE_NAME)

        gc.collect()
        baseline = len(sys.modules)

        for _ in range(100):
            importlib.import_module(PACKAGE_NAME)

        gc.collect()
        final = len(sys.modules)

        # Allow small tolerance for internal bookkeeping
        assert final - baseline < 5, (
            f"Module count grew by {final - baseline} — possible leak."
        )

    def test_import_idempotent(self):
        """Repeated imports must yield the same module object."""
        first = importlib.import_module(PACKAGE_NAME)
        second = importlib.import_module(PACKAGE_NAME)
        assert first is second, "Repeated imports yield different objects."


